CREATE TABLE workspace_sync_state (id INTEGER PRIMARY KEY CHECK(id=1), epoch TEXT NOT NULL);
INSERT INTO workspace_sync_state VALUES (1, lower(hex(randomblob(16))));
CREATE TABLE workspace_change (seq INTEGER PRIMARY KEY AUTOINCREMENT, workspace_id TEXT NOT NULL, collection TEXT NOT NULL, entity_id TEXT NOT NULL, op TEXT NOT NULL CHECK(op IN ('UPSERT','DELETE')), version INTEGER NOT NULL CHECK(version>=0));
CREATE INDEX workspace_change_cursor ON workspace_change(workspace_id,seq);
CREATE TRIGGER sync_work_item_insert AFTER INSERT ON work_item BEGIN INSERT INTO workspace_change(workspace_id,collection,entity_id,op,version) VALUES (NEW.workspace_id,'items',NEW.id,'UPSERT',NEW.version); END;
CREATE TRIGGER sync_work_item_update AFTER UPDATE ON work_item BEGIN INSERT INTO workspace_change(workspace_id,collection,entity_id,op,version) VALUES (NEW.workspace_id,'items',NEW.id,'UPSERT',NEW.version); END;
CREATE TRIGGER sync_work_item_delete AFTER DELETE ON work_item BEGIN INSERT INTO workspace_change(workspace_id,collection,entity_id,op,version) VALUES (OLD.workspace_id,'items',OLD.id,'DELETE',OLD.version); END;
